from scipy.optimize import least_squares
t=np.asarray(t); A=np.asarray(A); y=np.asarray(dA_dt)
def nmse(pred): return np.mean((pred-y)**2)/np.var(y)
forms = {
 'sep_H': lambda p: -(p[0]/t + p[1] + p[2]*t**2)/(1+p[3]*A) ,
 'sep_Hn': lambda p: -(p[0]/t + p[1] + p[2]*t**2)*A**p[4]/(1+p[3]*A**p[4]) ,
 'sep_exp': lambda p: -(p[0]/t + p[1] + p[2]*t**2)*np.exp(-p[3]*A) ,
 'tA': lambda p: -(p[0]/t + p[1] + p[2]*t**2)/(1+p[3]*A+p[4]*A*t) ,
 'tA2': lambda p: -(p[0]/t + p[1] + p[2]*t**2)*A/(p[3]+A+p[4]*A**2) ,
}
for name,f in forms.items():
    best=None
    for s in range(20):
        p0=np.random.RandomState(s).uniform(-2,2,5)
        try:
            r=least_squares(lambda p: f(p)-y, p0, max_nfev=3000)
            if best is None or r.cost<best.cost: best=r
        except Exception as e: pass
